function toxLabs(){return group('Wyniki (jednostki zgodne z ustawieniami; etanol ma własny wybór)',number('na','Na','mmol/l','',80,200)+number('k','K','mmol/l','',0,15)+number('cl','Cl','mmol/l','',30,200)+number('hco3','HCO₃','mmol/l','',0,60)+number('ph','pH','', '',6,8)+number('glu','Glukoza','','',0,70,'glu')+number('urea','Mocznik (urea, nie BUN)','','',0,100,'urea')+number('osm','Osmolalność ZMIERZONA','mOsm/kg','',150,600)+number('ethanol','Etanol oznaczony w laboratorium','','',0,1000)+select('ethanolUnit','Jednostka etanolu',[['mgdl','mg/dl'],['gL','g/l (liczbowo ≈ ‰ we krwi)'],['mmol','mmol/l']])+number('calcium','Ca zjonizowany','','',0,3,'ca')+number('lactate','Mleczany','mmol/l','',0,40));}
function toxData(g){const i={};['na','k','cl','hco3','ph','glu','urea','osm','ethanol','ethanolUnit','lactate','toxin','antidote','level','coma','seizure','vision','aki','persistentAcidosis','exposure'].forEach(k=>i[k]=g(k));return i;}
function gapsOutput(g){const r=E.gaps(toxData(g));return box('Luki: dwa różne wzory anionowe',table(['Wskaźnik','Wynik','Rachunek / interpretacja'],[['AG bez K (metanol)',F(r.ag,2)+' mmol/l','Na − Cl − HCO₃'],['AG z K (glikol, EXTRIP)',F(r.agK,2)+' mmol/l','Na + K − Cl − HCO₃'],['Osmolalność obliczona',F(r.calculated,2)+' mOsm/kg','2 × Na + glukoza + mocznik + etanol (wszystkie w mmol/l)'],['Luka osmolalna',F(r.osmGap,2)+' mOsm/kg','zmierzona − obliczona; nieobliczona przy brakującym etanolu']])+'<p>Etanol: mg/dl ÷4,607 =mmol/l; g/l ×100 ÷4,607. To wzór z idealnym wkładem etanolu; współczynnik laboratoryjny może się różnić. Podaj rzeczywisty wynik, także zero, nie zakładaj go. Prawidłowe luki nie wykluczają późnego ani wczesnego zatrucia. Niska albumina obniża AG; korekcji na albuminę nie wykonano. Porównaj jednostki i zakres laboratorium.</p>');}
function labCard(){return box('Kraków: Pracownia Toksykologiczna, Zakład Diagnostyki SU','<p><b>ul. Jakubowskiego 2, 30-688 Kraków, blok C, II piętro</b><br>Dyżur całodobowy: <a href="tel:+48124003649">12 400 36 49</a><br>Drugi numer pracowni: <a href="tel:+48124003614">12 400 36 14</a></p><p>Przed wysyłką uzgodnij badanie, materiał, objętość, probówki, temperaturę, transport, tryb i dostępność oznaczenia. Numer i adres potwierdzono na oficjalnej stronie SU oraz skierowaniu z 2024 r. Formularz SU wypełnia personel w systemie szpitalnym; ta aplikacja nie zbiera identyfikatorów pacjenta.</p>'+a('lab','Oficjalny kontakt')+' · '+a('referral','Aktualnie udostępnione skierowanie SU'));}
